new file mode 100644
index 00000000..cc1daa9e
--- /dev/null
+++ b/email-automation/courses/workbook-urls.json
@@ -0,0 +1,4 @@
+{
+  "_comment": "Current post-course workbook URLs, keyed by course type. Update ONE line here each quarter when the site's /materials/ slug rotates. Must be the direct PDF URL (bare files have no folder index), spaces %20-encoded. Keys starting with _ are ignored. See the site repo's CLAUDE.md 'Course workbooks' section.",
+  "CSPO": "https://agilepainrelief.com/materials/cspo-2026-q3-2922d7dfb842132c/CSPO%20Workbook.pdf"
+}
diff --git a/email-automation/src/course-config.ts b/email-automation/src/course-config.ts
index f407e97c..5de38e57 100644
--- a/email-automation/src/course-config.ts
+++ b/email-automation/src/course-config.ts
@@ -1,3 +1,6 @@
+import { readFileSync } from "fs";
+import { resolve } from "path";
+
 export interface MeetingInvite {
   zoomUrl: string;
   invitationUrl: string;
@@ -12,10 +15,73 @@ export interface CourseConfig {
   location?: string; // Default: "Virtual"
   muralLink: string;
   googleDocsFolder?: string;
-  dropboxFolder?: string; // Post-course training materials link
+  workbookUrl?: string; // Per-cohort override for the post-course workbook link; normally left unset (resolved by course type from workbook-urls.json)
+  dropboxFolder?: string; // Legacy post-course materials link; used only for courses not yet moved to /materials/
   meetingInvite: MeetingInvite;
 }

+// --- Post-course workbook URL ---
+
+let workbookUrlsCache: Record<string, string> | null = null;
+
+/** Load courses/workbook-urls.json once (keys starting with "_" are notes, not course types). */
+function loadWorkbookUrls(): Record<string, string> {
+  if (!workbookUrlsCache) {
+    const path = resolve(__dirname, "../courses/workbook-urls.json");
+    workbookUrlsCache = JSON.parse(readFileSync(path, "utf-8")) as Record<string, string>;
+  }
+  return workbookUrlsCache;
+}
+
+/**
+ * Resolve the hosted workbook link (the course workbook PDF on the APR site).
+ * NOTE: this is distinct from config.dropboxFolder, which is the per-cohort
+ * mural export folder shown as {{var:training_folder}}. Precedence:
+ *   1. config.workbookUrl        — per-cohort override for a one-off link
+ *   2. workbook-urls.json[type]  — current per-course link (updated quarterly)
+ * Returns null when the course has not been migrated to a hosted workbook yet
+ * (its post template then still hardcodes its own link). Callers that render or
+ * reachability-check the link must handle null.
+ */
+export function deriveWorkbookUrl(config: CourseConfig): string | null {
+  return config.workbookUrl ?? loadWorkbookUrls()[config.type] ?? null;
+}
+
+/** HEAD the URL; fall back to a 1-byte ranged GET if HEAD is refused. Returns 0 on network failure. */
+async function workbookUrlStatus(url: string): Promise<number> {
+  try {
+    const head = await fetch(url, { method: "HEAD" });
+    if (head.status !== 405 && head.status !== 501) return head.status;
+  } catch {
+    // fall through to a ranged GET
+  }
+  try {
+    const get = await fetch(url, { method: "GET", headers: { Range: "bytes=0-0" } });
+    return get.status === 206 ? 200 : get.status; // 206 Partial Content also means the file is served
+  } catch {
+    return 0;
+  }
+}
+
+/**
+ * Verify the workbook URL is live before anyone is emailed it. Scoped to
+ * APR-hosted /materials/ links (the hand-pasted random slug is the fragile bit);
+ * legacy Dropbox links are skipped since they don't answer HEAD reliably.
+ * Throws on a non-200 so the caller can abort the send. Note: this proves the
+ * link is live, not that it's the right (current) workbook.
+ */
+export async function assertWorkbookReachable(url: string): Promise<void> {
+  if (!/^https:\/\/agilepainrelief\.com\/materials\//.test(url)) {
+    console.log(`Skipping reachability check for non-materials workbook URL: ${url}`);
+    return;
+  }
+  const status = await workbookUrlStatus(url);
+  if (status !== 200) {
+    throw new Error(`Workbook URL is unreachable (HTTP ${status || "no response"}): ${url}`);
+  }
+  console.log(`Workbook URL OK (200): ${url}`);
+}
+
 /**
  * Build the "other ways to join" block for display in emails. The one-click
  * join button (zoomUrl) is rendered separately by the template; everything
diff --git a/email-automation/src/send-course-email.ts b/email-automation/src/send-course-email.ts
index c51578ae..28ff7949 100644
--- a/email-automation/src/send-course-email.ts
+++ b/email-automation/src/send-course-email.ts
@@ -14,6 +14,8 @@ import {
   deriveClassTimes,
   buildGoogleCalendarUrl,
   buildOutlookCalendarUrl,
+  deriveWorkbookUrl,
+  assertWorkbookReachable,
 } from "./course-config";
 import { buildPrefillSignupUrl } from "./signup-url";
 import {
@@ -195,9 +197,16 @@ function renderMarkdownEmail(
   // Replace template variables in the body HTML
   let rendered = bodyHtml;

+  // marked percent-encodes the braces of any {{var:...}} placeholder that sits in
+  // a link URL, e.g. `[label]({{var:workbook_link}})` becomes
+  // href="%7B%7Bvar:workbook_link%7D%7D". Decode those back so the substitution
+  // below matches placeholders in link-URL positions, not just text positions.
+  rendered = rendered.replace(/%7B%7B/gi, "{{").replace(/%7D%7D/gi, "}}");
+
   const vars: Record<string, string> = {
     first_name: student.firstName,
-    training_folder: config.dropboxFolder ?? "",
+    training_folder: config.dropboxFolder ?? "", // per-cohort mural export folder
+    workbook_link: deriveWorkbookUrl(config) ?? "", // hosted workbook PDF (empty until the course is migrated)
   };

   for (const [key, value] of Object.entries(vars)) {
@@ -256,6 +265,7 @@ function renderTemplate(
     mural_link: config.muralLink,
     zoom_link: zoomLink,
     meeting_invite: deriveMeetingInviteHtml(config),
+    workbook_link: deriveWorkbookUrl(config) ?? "", // hosted workbook PDF (empty until the course is migrated; guarded by the preflight)
   };

   if (config.googleDocsFolder) {
@@ -329,6 +339,7 @@ async function main(): Promise<void> {
       process.exit(1);
     }
   } else {
+    // Post-course: {{var:training_folder}} is the per-cohort mural export folder.
     if (!config.dropboxFolder) missing.push("dropboxFolder");
   }
   if (missing.length > 0) {
@@ -336,6 +347,39 @@ async function main(): Promise<void> {
     process.exit(1);
   }

+  // Workbook preflight: fires for whichever email (pre or post) whose template
+  // links the hosted workbook via {{var:workbook_link}}. For such a course,
+  // require a configured URL and verify it is live, so a typo'd slug, an unpushed
+  // folder, or a filename mismatch aborts before emailing a dead link. Runs in
+  // --dry-run too. Templates that still hardcode a link are left untouched.
+  const workbookTemplatePath =
+    cliArgs.emailType === "post"
+      ? resolve("templates/course", `post-${config.type.toLowerCase()}.md`)
+      : resolve("templates/course", `${cliArgs.emailType}-${config.type.toLowerCase()}.html`);
+  let workbookTemplateBody = "";
+  try {
+    workbookTemplateBody = readFileSync(workbookTemplatePath, "utf-8");
+  } catch {
